+{
+  "version": "1.0",
+  "scope": "explicit typed operations and bounded supplied data; not natural-language inference or external outcome proof",
+  "baseline_required_for_superiority": [
+    "always raw local LLM",
+    "strongest eligible licensed local LLM",
+    "LLM router",
+    "best eligible specialized solver",
+    "strongest simple baseline"
+  ],
+  "baseline_availability": "UNAVAILABLE here; record no superiority/regret estimate until all required predeclared comparisons are measured",
+  "cases": [
+    {
+      "id": "bounded:calculate",
+      "request": {
+        "problem_id": "test:calculate",
+        "operation": "calculate",
+        "data": {
+          "expression": "0.1 + 0.2"
+        }
+      },
+      "expected": {
+        "method": "cognition.exact",
+        "state": "NONE",
+        "output": {
+          "exact": "3/10"
+        }
+      }
+    },
+    {
+      "id": "bounded:polynomial",
+      "request": {
+        "problem_id": "test:polynomial",
+        "operation": "polynomial",
+        "data": {
+          "polynomial": [
+            -4,
+            0,
+            1
+          ]
+        }
+      },
+      "expected": {
+        "method": "cognition.exact",
+        "state": "NONE",
+        "output": {
+          "real_roots": [
+            "-2",
+            "2"
+          ]
+        }
+      }
+    },
+    {
+      "id": "bounded:estimate",
+      "request": {
+        "problem_id": "test:estimate",
+        "operation": "estimate",
+        "data": {
+          "factors": [
+            {
+              "name": "n",
+              "low": 2,
+              "central": 3,
+              "high": 4
+            },
+            {
+              "name": "p",
+              "low": 5,
+              "central": 6,
+              "high": 7
+            }
+          ]
+        }
+      },
+      "expected": {
+        "method": "cognition.estimation",
+        "state": "NONE",
+        "output": {
+          "central": 18
+        }
+      }
+    },
+    {
+      "id": "bounded:constraints",
+      "request": {
+        "problem_id": "test:constraints",
+        "operation": "constraints",
+        "data": {
+          "variables": {
+            "x": [
+              0,
+              10
+            ],
+            "y": [
+              0,
+              10
+            ]
+          },
+          "constraints": [
+            {
+              "coefficients": {
+                "x": 1,
+                "y": 1
+              },
+              "op": ">=",
+              "rhs": 5
+            }
+          ]
+        }
+      },
+      "expected": {
+        "method": "cognition.formal",
+        "state": "NONE",
+        "output": {
+          "solver_status": "SAT"
+        }
+      }
+    },
+    {
+      "id": "bounded:optimize",
+      "request": {
+        "problem_id": "test:optimize",
+        "operation": "optimize",
+        "data": {
+          "variables": {
+            "x": [
+              0,
+              10
+            ],
+            "y": [
+              0,
+              10
+            ]
+          },
+          "constraints": [
+            {
+              "coefficients": {
+                "x": 1,
+                "y": 1
+              },
+              "op": ">=",
+              "rhs": 5
+            }
+          ],
+          "objective": {
+            "coefficients": {
+              "x": 1,
+              "y": 2
+            },
+            "sense": "min"
+          }
+        }
+      },
+      "expected": {
+        "method": "cognition.optimization",
+        "state": "NONE",
+        "output": {
+          "objective_value": 5
+        }
+      }
+    },
+    {
+      "id": "bounded:shortest_path",
+      "request": {
+        "problem_id": "test:shortest_path",
+        "operation": "shortest_path",
+        "data": {
+          "edges": [
+            [
+              "a",
+              "b",
+              2
+            ],
+            [
+              "b",
+              "c",
+              3
+            ],
+            [
+              "a",
+              "c",
+              9
+            ]
+          ],
+          "start": "a",
+          "goal": "c"
+        }
+      },
+      "expected": {
+        "method": "cognition.graph",
+        "state": "NONE",
+        "output": {
+          "cost": 5
+        }
+      }
+    },
+    {
+      "id": "bounded:state_search",
+      "request": {
+        "problem_id": "test:state_search",
