+            ]
+          ]
+        }
+      },
+      "expected": {
+        "method": "cognition.causal",
+        "state": "NONE",
+        "output": {
+          "effect": 3
+        }
+      }
+    },
+    {
+      "id": "bounded:pid",
+      "request": {
+        "problem_id": "test:pid",
+        "operation": "pid",
+        "data": {
+          "observed": 2,
+          "target": 10,
+          "kp": 2,
+          "correction_limit": 3
