+            {
+              "probability": 0.5,
+              "best_value": 12
+            }
+          ]
+        }
+      },
+      "expected": {
+        "method": "cognition.information",
+        "state": "NONE",
+        "output": {
+          "net_value": 2
+        }
+      }
+    },
+    {
+      "id": "bounded:simulate",
+      "request": {
+        "problem_id": "test:simulate",
+        "operation": "simulate",
+        "data": {
+          "seed": 3,
+          "samples": 10,
+          "steps": 2,
+          "step_probability": 1
+        }
+      },
+      "expected": {
+        "method": "cognition.simulation",
+        "state": "NONE",
+        "output": {
+          "mean": 2
+        }
+      }
+    },
+    {
+      "id": "bounded:minimax",
+      "request": {
+        "problem_id": "test:minimax",
+        "operation": "minimax",
+        "data": {
+          "payoffs": [
+            [
+              1,
+              -1
+            ],
+            [
+              -1,
+              1
+            ]
+          ]
+        }
+      },
+      "expected": {
+        "method": "cognition.game",
+        "state": "NONE",
+        "output": {
+          "value": 0
+        }
+      }
+    },
+    {
+      "id": "bounded:anomalies",
+      "request": {
+        "problem_id": "test:anomalies",
+        "operation": "anomalies",
+        "data": {
+          "observations": [
